// Accepts one event, an array of events, or {"events": [...]}.
const body = $input.first().json.body ?? {};
const events = Array.isArray(body) ? body : (Array.isArray(body.events) ? body.events : [body]);

if (events.length === 0 || events.length > 5000) {
  throw new Error(`Expected 1-5000 events, got ${events.length}`);
}

return [{ json: { events: events.map(e => ({
  case_id: e.case_id != null ? String(e.case_id).trim() : null,
  stage: e.stage != null ? String(e.stage).trim().toLowerCase() : null,
  event_ts: e.event_ts ?? null,
  source: e.source ?? 'api',
  payload: e.payload ?? {},
})) } }];
